 Context c;
 @Before public void reset(){c=RuntimeEnvironment.getApplication();for(String key:new String[]{"project_dark_f5m_v1","project_dark_skill_book_v1","project_dark_skill_test_v1"})c.getSharedPreferences(key,0).edit().clear().commit();F5mSaveStore.install(c);}
 static final String[] SKILLS={"SK_전사_003","SK_도적_007","SK_마법사_014","SK_성직자_013","SK_무도가_007"};
 RuntimeState huntingState;WorldRuntimeAdapter huntingWorld;CampaignProgress.Def huntingQuest;
 String activeSkill,scenario=""; String skill(String job){return activeSkill!=null?activeSkill:SKILLS[Arrays.asList(CampaignProgress.JOBS).indexOf(job)];}
 void allocate(RuntimeState s){String job=s.rpg().currentJobCode();String a=job.equals("MAGE")||job.equals("CLERIC")?"INT":"STR",z=job.equals("MAGE")||job.equals("CLERIC")?"WIS":job.equals("ROGUE")?"DEX":"CON";int i=0;while(s.rpg().statPoints()>0)assertTrue(s.rpg().spendStat(i++%2==0?a:z));s.applyDerivedGrowth();}
 void stock(RuntimeState s){for(String id:new String[]{RpgProgressionState.REAGENT_CURANUM_ITEM_ID,"IT_B_MP_POTION"}){int count=(id.equals("IT_B_MP_POTION")?40:s.rpg().normalLevel()>=43?40:20)-s.rpg().inventory().getOrDefault(id,0);if(count>0)assertEquals("paid stock between quest waves "+s.rpg().currentJobCode()+" "+s.rpg().campaign().activeId(),TownCommerce.Result.OK,TownCommerce.transact(s,TownInteriorDef.Kind.REAGENT,TownCommerce.Operation.BUY,id,count,()->true));}}
 String spellFor(RuntimeState s,SkillBook b,RuntimeState.Monster target){String id=skill(s.rpg().currentJobCode());if(!s.rpg().currentJobCode().equals("MAGE"))return id;String[] spells={"SK_마법사_013","SK_마법사_014","SK_마법사_015","SK_마법사_016"},elements={"WATER","EARTH","WIND","FIRE"};int best=-1;AbelCombatProfile p=AbelCombatProfile.forId(target.id);for(int i=0;i<4;i++)if(b.usable(spells[i])){int damage=ElementalDamageFormula.apply(100,elements[i],p.element.equals("LIFE")?"NONE":p.element);if(damage>best){best=damage;id=spells[i];}}return id;}
 void gear(RuntimeState s,int level){for(String id:new String[]{"IT_B_CAMPAIGN_"+s.rpg().currentJobCode()+"_"+level,"IT_B_CAMPAIGN_TOOL_"+s.rpg().currentJobCode()+"_"+level}){if(s.rpg().inventory().getOrDefault(id,0)==0)assertTrue("normal merchant purchase",TownCommerce.transact(s,TownInteriorDef.Kind.EQUIPMENT,TownCommerce.Operation.BUY,id,1,()->true)==TownCommerce.Result.OK);assertEquals(RpgProgressionState.EquipResult.EQUIPPED,s.rpg().equip(id));}s.applyDerivedGrowth();}
 void learn(RuntimeState s,SkillBook b,String id){SkillAcquisition a=new SkillAcquisition(b);for(int i=0;i<5;i++){SkillAcquisition.Quote q=a.quote(b.get(id),s.rpg());int n=0;while(q.current[i]<q.required[i]&&s.rpg().statPoints()>0&&n++<200){assertTrue(s.rpg().spendStat(SkillAcquisition.STATS[i]));q=a.quote(b.get(id),s.rpg());}}assertTrue(id+" normal learning: "+a.quote(b.get(id),s.rpg()).blockers,a.learn(id,s.rpg()));assertTrue(b.assign(0,id));assertFalse(b.testAccess());}
 void consume(RuntimeState s,String id){assertTrue("previously purchased stock survives "+scenario+" / "+id+" seconds="+seconds+" potions="+potions+" casts="+casts+" gold="+s.rpg().gold(),s.rpg().inventory().getOrDefault(id,0)>0);assertEquals(RpgProgressionState.UseResult.USED,s.rpg().useConsumable(id,s));}
 int potions,defeats;long observedSequence;float seconds;int casts;boolean playerBusy;final Map<String,Float> deferred=new HashMap<>();
 void frame(RuntimeState s,RuntimeCombatSession combat,MonsterAIController ai,WorldRuntimeAdapter world,SkillBook b){RuntimeCombatSession.FrameResult result=combat.tick(.05f);playerBusy=false;for(CombatResolver.ActionSnapshot a:result.actions)if(a.actorId.equals("player")){playerBusy=true;break;}Set<Long> practiced=new HashSet<>();for(CombatResolver.Event e:result.events)if(e.type==CombatResolver.EventType.EFFECT_APPLIED&&e.actorId.equals("player")&&practiced.add(e.actionSequence))b.practiced(e.actionId.startsWith("attack_proto_")?"SK_공통_001":e.actionId);s.tick(.05f);for(CombatLedger.Event e:s.ledger().snapshot())if(e.sequence>observedSequence){if(e.type==CombatLedger.Type.MONSTER_DEFEATED)defeats++;observedSequence=e.sequence;}s.applyDerivedGrowth();ai.tick(s,.05f);if(world!=null){if(s.skillEffects().rooted("player"))world.cancelForAction();else world.tickNavigation(.05f);}seconds+=.05f;if(s.player().alive&&s.player().hp<s.player().maxHp*.65f){consume(s,RpgProgressionState.REAGENT_CURANUM_ITEM_ID);potions++;}if(s.player().alive&&s.player().mp<s.player().maxMp*.2f){consume(s,"IT_B_MP_POTION");potions++;}assertTrue("normal build survives active monster AI",s.player().alive);}
 boolean visible(RuntimeState s,WorldRuntimeAdapter w,String id){if(id.equals("player"))return true;RuntimeState.Monster m=SkillEffectState.monster(s,id);if(w==null||m==null)return false;WorldCameraTransform.Point p=w.worldToScreen(m.x,m.y);return p.x>=0&&p.x<960&&p.y>=0&&p.y<540;}
 RuntimeState.Monster select(RuntimeState s,WorldRuntimeAdapter w,CampaignProgress.Def d){
  SkillActionContract.Rule rule=SkillActionContract.get(skill(s.rpg().currentJobCode()));RuntimeState.Monster best=null;double dist=Double.MAX_VALUE;
  for(RuntimeState.Monster m:s.monsters())if(m.alive&&s.rpg().campaign().wanted(d,m.campaignRewardProfileId)&&seconds>=deferred.getOrDefault(m.id,0f)&&visible(s,w,m.id)&&w.hasCombatLineOfSight("player",m.id)&&SkillApproachController.legal(rule,s.player().x,s.player().y,m.x,m.y)){double n=Math.hypot(m.x-s.player().x,m.y-s.player().y);if(n<dist){dist=n;best=m;}}
  if(best!=null)return best;if(rule.kind.equals("마법")){best=SkillApproachController.reachableTarget(w,rule,m->s.rpg().campaign().wanted(d,m.campaignRewardProfileId)&&seconds>=deferred.getOrDefault(m.id,0f),960,540);if(best!=null)return best;}best=w.selectAutoTarget(m->s.rpg().campaign().wanted(d,m.campaignRewardProfileId)&&seconds>=deferred.getOrDefault(m.id,0f));
  // A nearby non-quest hostile can occupy the approach corridor; clear it through normal combat.
  if(best==null&&!s.skillEffects().rooted("player"))best=w.selectAutoTarget(m->Math.hypot(m.x-s.player().x,m.y-s.player().y)<180&&seconds>=deferred.getOrDefault(m.id,0f));return best;
 }
 boolean hunt(RuntimeState s,RuntimeCombatSession combat,MonsterAIController ai,SkillBook b,WorldRuntimeAdapter world,RuntimeState.Monster target){
  scenario=s.rpg().currentJobCode()+" "+s.rpg().campaign().activeId()+" "+target.id;int frames=0,stalled=0,lastHp=target.hp;float before=seconds;
  SkillActionContract.Rule rule=SkillActionContract.get(skill(s.rpg().currentJobCode()));float plannedX=Float.NaN,plannedY=Float.NaN;
  while(target.alive&&frames++<5000){
   if(!playerBusy&&!world.presentationMoving()){
    if(visible(s,world,target.id)&&world.hasCombatLineOfSight("player",target.id)&&SkillApproachController.legal(rule,s.player().x,s.player().y,target.x,target.y)){
     world.cancelForAction();CombatActionOrchestrator.Submission cast=combat.submitPlayer(rule.selfAnchored()?"player":target.id,spellFor(s,b,target));if(cast.accepted()){casts++;playerBusy=true;}else if(CanonicalMeleeTileContract.reachable(s.player().x,s.player().y,target.x,target.y))playerBusy=combat.submitPlayerBasicAttack(target.id).combat.accepted();
    }else if(!s.skillEffects().rooted("player")){
     float tx=target.isMoving?target.moveTargetX:target.x,ty=target.isMoving?target.moveTargetY:target.y;if(tx!=plannedX||ty!=plannedY||world.movement().snapshot().status==WorldMoveTargetController.Status.BLOCKED){List<WorldMoveTargetController.TileCenter> path=SkillApproachController.path(world,rule,target,960,540);if(path==null){frame(s,combat,ai,world,b);deferred.put(target.id,seconds+3);return false;}plannedX=tx;plannedY=ty;world.movement().requestSkillApproach(target.id,path);}
    }
   }
   frame(s,combat,ai,world,b);if(target.hp<lastHp){lastHp=target.hp;stalled=0;}else if(++stalled>200&&!playerBusy){deferred.put(target.id,seconds+3);return false;}
  }assertFalse("real attack defeats "+scenario+" hp="+target.hp+" casts="+casts,target.alive);assertTrue("bounded fight including live navigation",seconds-before<250);return true;
 }
 JSONObject diagnostic()throws Exception{JSONObject out=new JSONObject();RuntimeState s=huntingState;WorldRuntimeAdapter w=huntingWorld;CampaignProgress.Def d=huntingQuest;if(s==null||w==null||d==null)return out;out.put("map",s.currentMapId()).put("playerX",s.player().x).put("playerY",s.player().y).put("rooted",s.skillEffects().rooted("player")).put("navigationCenter",s.isMonsterTileCenter(s.player().x,s.player().y)).put("movement",w.movement().snapshot().status.name()).put("presentationMoving",w.presentationMoving()).put("questCount",s.rpg().campaign().count(d,s.rpg()));JSONArray wanted=new JSONArray();for(RuntimeState.Monster m:s.monsters())if(s.rpg().campaign().wanted(d,m.campaignRewardProfileId))wanted.put(new JSONObject().put("id",m.id).put("alive",m.alive).put("hp",m.hp).put("x",m.x).put("y",m.y).put("respawn",m.respawnClock).put("visible",visible(s,w,m.id)).put("meleePathSteps",m.alive?w.monsterApproachPathSteps(m.id,48):-1).put("skillPath",m.alive&&SkillApproachController.path(w,SkillActionContract.get(skill(s.rpg().currentJobCode())),m,960,540)!=null));out.put("wanted",wanted);return out;}
 void writeTrace(JSONArray trace)throws Exception{Path p=Paths.get("build/reports/abel-v153/quest-progress.json");Files.createDirectories(p.getParent());Files.write(p,trace.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
